<?php
namespace App\Features\Vehicles\Requests;
use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class VehicleRequest extends FormRequest { public function authorize(): bool{return $this->user()?->can($this->isMethod('post')?'vehicle.create':'vehicle.update')??false;} public function rules(): array { $id=$this->route('vehicle'); return ['customer_id'=>['nullable','uuid','exists:customers,id'],'registration_number'=>['required','string','max:32',Rule::unique('vehicles')->where(fn($q)=>$q->where('tenant_id',$this->user()->tenant_id))->ignore($id)],'chassis_number'=>['required','string','max:64'],'engine_number'=>['nullable','string','max:64'],'manufacturer'=>['required','string','max:100'],'model'=>['required','string','max:100'],'variant'=>['nullable','string','max:100'],'fuel_type'=>['required','in:petrol,diesel,cng,electric,hybrid,other'],'colour'=>['nullable','string','max:50'],'manufacture_year'=>['nullable','integer','min:1900','max:'.(now()->year+1)],'registration_date'=>['nullable','date'],'status'=>['required','in:active,sold,scrapped,inactive'],'notes'=>['nullable','string','max:4000']]; } }
